solutionCode:
pub fn o_leite_de(leite: i32) -> Option<i32> {
    if leite > 0 {
        Some(leite * 2)
    } else {
        None
    }
}

pub fn o_dobro_garantido(leite: i32) -> i32 {
    let caixa = o_leite_de(leite);
    caixa.unwrap()
}

pub fn o_dobro_com_motivo(leite: i32) -> i32 {
    let caixa = o_leite_de(leite);
    caixa.expect("o leite do dia precisa ser positivo")
}

